// Cloudflare Worker entry — free tier, no bindings.
// Mirrors server.js routes using Web APIs. Deploy: `npx wrangler deploy`.
const SKILLS = [
  { id: "code-index", track: "code", title: "Start here: task first, stack second", tokens: "~680", why: "One tiny map keeps every other skill small: the agent reads hundreds of tokens, not thousands.", prompt: "Create and install a skill named `code-index` (Start here: pick skills by task). It instructs the agent as follows: Your installed skills each do one job — never read them all. Step zero: detect the codebase's language, framework, and tokens before matching anything. Bound to a stack? The house defaults never apply — follow the codebase and skip or overwrite every conflicting house skill. We default to Python plus FastAPI plus Pydantic and Lit only for new, unbound work because agents generate it fastest with the fewest mistakes — never force it on an existing codebase. Work in two passes. Pass 1 — task first. Three skills apply to almost every task, so always read these: code-secure, code-reuse, code-token. Then match the task and read only the matched skills — mixed tasks match more than one line, so a UI-plus-API job reads ui-index and the service skills: Interface, screen, or component work → ui-index. New service or script → code-language, code-shape. Organizing a new codebase → code-group. Services in other languages → code-boundaries, then code-polyglot for the guest side. Public API, forms, beacons → code-ratelimit. Repeat traffic → code-cache. Usage counts → code-track. Slow endpoint or heavy page → code-perf. Work that outlives the request → code-async. Background jobs, queues, workers, and parallel fan-out also land on code-async. Traffic spikes, shedding features → code-fallback. Login, accounts, permissions → code-auth. Product features (billing, roles, admin — any SaaS, SIS, billing system) → app-index. Landing data and scheduling pipelines → data-index. Build-test-deploy gates and paging → ops-index. Two or more agents sharing one deploy or codebase → ops-index too. Vuln deadlines, enterprise login, regulated data → sec-index. Security deep-dives — the OWASP Top 10 set, read on match: code-crypto, code-injection, code-design, code-misconfig, code-deps, code-integrity, code-logging, code-ssrf. Pass 2 — stack specifics. After the task match, apply the stack the codebase already uses: language → code-language (Python first on new code; if the project already uses another language, skip this skill or overwrite it with that stack). Interface framework → ui-index (house default Lit via ui-framework; widget libraries per framework live in ui-platform-picks). Styling → ui-tokens (unless the project already has a design system — then skip it). Mobile platform → ui-mobile (Capacitor shell unless native is technically required). Service-to-service → code-boundaries (same-language HTTP, other languages gRPC, events validated). These stack picks assume a new codebase: if the project already uses something else — another language, framework, tokens, or platform — follow that instead. The house rule beats the skill. Skip everything else. Fetch all matched skills in one batched request; never fetch the same skill twice in one session — installed skills live locally. When building is done → verify-tests, plus verify-visual for screens and verify-layout for layout. Three or more matched skills → code-plan first. Missing a skill? Copy its prompt from the skills page once, install it, then use it locally. This follows progressive disclosure — map first, details on demand.", checks: ["only matched skills are read", "always-on skills never skipped", "whole bank never copied at once"] },
  { id: "code-language", track: "code", title: "Python first, house wins", tokens: "~290", why: "Frameworks make whole mistake classes unwritable, so the agent spends tokens on the task instead of on validation and plumbing.", prompt: "Create and install a skill named `code-language` (Python first, house wins). It instructs the agent as follows: Default to Python — agents generate it fastest, with the fewest mistakes. Write services with FastAPI + Pydantic: one model drives routing, validation, and the OpenAPI schema — never hand-write type checks. One SQLModel class serves as both table and validator. CLIs are one Typer-decorated function. Type everything; let the framework and tests catch errors, not code review. If the codebase already uses another language, do not create this skill at all — skip it. Framework first: use the framework's own piece for anything it covers; hand-write only what no framework covers. Between same-language services reuse the same models; when sibling services differ, use gRPC between services and keep the edge framework at the edge. If the project already uses a different stack, overwrite this skill with that stack's equivalent and follow it instead.", checks: ["all I/O typed", "no hand-written validators", "tests cover happy path + one edge"] },
  { id: "ui-mobile", track: "ui", title: "Mobile: FastAPI + HTMX + Tailwind + Capacitor", tokens: "~220", why: "One language and zero client state means the agent writes every feature once and it ships to both app stores.", prompt: "Create and install a skill named `ui-mobile` (Mobile: FastAPI + HTMX + Tailwind + Capacitor). It instructs the agent as follows: Build mobile apps as server-rendered HTML: FastAPI routes return fragments, HTMX attributes (hx-get/hx-target) give SPA behavior with near-zero JavaScript, Tailwind utilities handle responsive layout inline, Capacitor wraps the mobile viewport into iOS/Android shells. No client state, no fetch calls, no Swift/Kotlin.  If the project already uses a different mobile stack, do not create this skill at all — skip it.", checks: ["zero hand-written fetch calls", "no client-side state store", "layout verified at 360px width"] },
  { id: "code-token", track: "code", title: "Token-efficient code", tokens: "~190", why: "Every token spent writing or re-reading code is a token not spent on the task; cheap code compounds across sessions.", prompt: "Create and install a skill named `code-token` (Token-efficient code). It instructs the agent as follows: Write code that's cheap to generate and cheap to re-read: type everything, one canonical pattern per job (FastAPI route, Pydantic model, Typer command). Early returns, table-driven branches over nested ifs, JSON-first data. Delete dead code — every dead line taxes every future read. Prefer 20 lines of plain code over 5 lines of clever code.", checks: ["no nested depth >2", "no dead exports", "single pattern per job"] },
  { id: "code-secure", track: "code", title: "Secure by default", tokens: "~120", why: "Insecure code fails late and expensively; validated boundaries fail fast on the first bad input.", prompt: "Create and install a skill named `code-secure` (Secure by default). It instructs the agent as follows: Validate every input at the boundary", checks: ["all inputs validated", "no eval/innerHTML with raw input", "no secret in repo"] },
  { id: "code-auth", track: "code", title: "Login and permissions", tokens: "~220", why: "Authentication is the most-broken OWASP category; one shared login path removes the whole class.", prompt: "Create and install a skill named `code-auth` (Login and permissions). It instructs the agent as follows: Logins use signed cookies (built into Starlette — one secret key, no extra package). Sign in with Google uses authlib. Services talking to each other use JWTs via pyjwt. Passwords are checked with bcrypt via passlib — never write your own password check, because a wrong one fails silently and an agent will not notice. For every action, check the permission at the boundary and default to deny: never trust a role or user id sent by the client, always re-check it on the server.", checks: ["sessions are signed cookies", "passwords via bcrypt only", "permission checked per action, default deny"] },
  { id: "code-crypto", track: "code", title: "No homegrown crypto", tokens: "~180", why: "Homegrown crypto fails silently; platform crypto fails loudly and rarely.", prompt: "Create and install a skill named `code-crypto` (No homegrown crypto). It instructs the agent as follows: Use vetted crypto only: TLS for data in motion, platform encryption (KMS, age, or libsodium) for data at rest — never a hand-rolled cipher. Secrets live in environment variables, never in code or logs. Passwords are hashed, not encrypted (see code-auth); API tokens are random, scoped, and expire.", checks: ["no hand-rolled ciphers", "no secret in code or logs", "tokens expire and are scoped"] },
  { id: "code-injection", track: "code", title: "Input stays data", tokens: "~160", why: "Injection is input treated as instructions; parameters keep input as data.", prompt: "Create and install a skill named `code-injection` (Input stays data). It instructs the agent as follows: Never build queries, commands, or markup by gluing strings around user input. Database reads go through the ORM (SQLModel parameterizes everything). Templates auto-escape HTML — never mark user content safe. OS commands, LDAP, and XPath get the same rule: parameters, never concatenation.", checks: ["no string-built queries or commands", "user HTML never marked safe", "ORM or parameters everywhere"] },
  { id: "code-design", track: "code", title: "Abuse story first", tokens: "~160", why: "Missing controls can't be patched in later without redesigning the feature.", prompt: "Create and install a skill named `code-design` (Abuse story first). It instructs the agent as follows: For each feature, ask how it is abused before asking how it is used: who pays for heavy use, who is hurt by bad input. Default to deny, grant least privilege, rate-limit costly endpoints, and cap upload and response sizes. A feature without an abuse story is not designed yet.", checks: ["abuse story per feature", "default deny", "costly endpoints rate-limited"] },
  { id: "code-misconfig", track: "code", title: "Safe settings shipped", tokens: "~160", why: "Most breaches walk through doors the defaults left open.", prompt: "Create and install a skill named `code-misconfig` (Safe settings shipped). It instructs the agent as follows: Ship with the safe settings on: debug and trace off in production, generic error pages that leak nothing, strict transport security and a content security policy, CORS allowlists instead of wildcards, and no default passwords or open admin pages. Review headers and flags on every deploy, not once.", checks: ["debug off in production", "security headers set", "no defaults or wildcards"] },
  { id: "code-deps", track: "code", title: "Dependencies audited", tokens: "~150", why: "Your code inherits every vulnerability in every library it imports.", prompt: "Create and install a skill named `code-deps` (Dependencies audited). It instructs the agent as follows: Pin every dependency (requirements with versions), audit on a schedule (pip audit or equal), and update promptly when a fix lands. Fewer dependencies means fewer advisories: drop what the stack already covers. Never vendor a copy you will forget to patch.", checks: ["deps pinned with versions", "audit runs on schedule", "unused deps removed"] },
  { id: "code-integrity", track: "code", title: "Verify before trust", tokens: "~160", why: "A build that can't prove what it contains can't prove what it ships.", prompt: "Create and install a skill named `code-integrity` (Verify before trust). It instructs the agent as follows: Trust nothing you didn't verify: lockfiles pin the whole tree, webhook handlers check signatures before acting, CI runs tests before deploys, and installs come from registries — never pipe a URL to a shell. If bytes changed without a commit, stop and ask.", checks: ["lockfiles committed", "webhook signatures verified", "no curl-to-shell installs"] },
  { id: "code-logging", track: "code", title: "Logs that catch break-ins", tokens: "~170", why: "You can't respond to an attack you never recorded or never noticed.", prompt: "Create and install a skill named `code-logging` (Logs that catch break-ins). It instructs the agent as follows: Log the events that catch break-ins: failed logins, validation failures, permission denials, and spikes in costly endpoints. Keep logs structured (who, what, when) and secret-free — logs get copied and shared. Watch them with an alert, not just storage: an unread log is decoration.", checks: ["auth and deny events logged", "no secrets in logs", "alerts on spikes, not just storage"] },
  { id: "code-ssrf", track: "code", title: "Server fetches allowlisted", tokens: "~170", why: "A server that fetches arbitrary URLs becomes a proxy into your own network.", prompt: "Create and install a skill named `code-ssrf` (Server fetches allowlisted). It instructs the agent as follows: Never fetch a user-supplied URL from the server without an allowlist: block internal addresses and cloud metadata (169.254.169.254), resolve and re-check the host, and cap timeouts and response sizes. Prefer webhooks and signed callbacks over server-side fetching whenever the design allows.", checks: ["user URLs allowlisted", "metadata IP blocked", "timeouts and size caps set"] },
  { id: "code-ratelimit", track: "code", title: "Throttle the expensive doors", tokens: "~230", why: "An unthrottled endpoint is a counter-inflation and outage tool for anyone with a loop.", prompt: "Create and install a skill named `code-ratelimit` (Throttle the expensive doors). It instructs the agent as follows: Throttle expensive endpoints per client: a sliding window (for example 120 requests per minute per IP on API routes) — public reads get room, writes and beacons get less. Answer over-limit with 429 plus a Retry-After header, never a crash page. Keep limits in config, not code, so they change without a deploy. Count blocked requests separately so attacks show up in stats instead of hiding in totals. Behind a CDN, prefer its edge rules; the built-in limiter is the second layer, not the first.", checks: ["expensive routes throttled per client", "429 carries Retry-After", "limits live in config"] },
  { id: "code-boundaries", track: "code", title: "Service boundaries", tokens: "~220", why: "The wrong protocol between services costs speed forever; the right one is a one-line decision made once.", prompt: "Create and install a skill named `code-boundaries` (Service boundaries). It instructs the agent as follows: Connect services by rule, not habit: same Python system → shared Pydantic models over HTTP; other languages or hot internal paths → protobuf plus gRPC, FastAPI stays at the edge; events and queues → Pydantic-validated messages. Writing the guest side → code-polyglot. Build the whole app in Python by default, but carve out other languages where Python technically fails: single-digit-millisecond budgets use Go or Rust, over 100k live connections use Erlang or Elixir, heavy offline clients and games and widgets go native.", checks: ["protocol chosen by rule, not default", "non-Python parts named with their technical reason", "FastAPI at the edge in mixed systems"] },
  { id: "ui-shell", track: "ui", title: "UI shell in 40 lines", tokens: "~320", why: "Humans get the interface they prefer; metadata makes it legible to agents without dumbing it down.", prompt: "Create and install a skill named `ui-shell` (UI shell in 40 lines). It instructs the agent as follows: Build mobile-first: design at 360px width, then scale up — full-monitor layouts only when the task genuinely needs a big screen. Semantic HTML shell (<header>/<main>/<footer>), one stylesheet, no UI framework. System font stack, 2 colors + 1 accent, 4px spacing scale. Humans get the UI they prefer — icon-only buttons and custom controls included — but every control must expose machine-readable metadata: a real <button>/<a>/<input>, a visible label or aria-label, and a data-action naming what it does. Pull icons from Lucide: `<i data-lucide='name'>` plus one `lucide.createIcons()` call; never hand-write SVG paths — the agent picks icon names, not pixels. Hand-drawn icons burn tokens and time for a worse result: Lucide is already in the model's training so the agent knows every name, and already familiar to users so people recognize each icon on sight.", checks: ["layout verified at 360px width", "every control has a label or aria-label", "custom controls expose role + data-action"] },
  { id: "ui-tokens", track: "ui", title: "Tokens + Tailwind", tokens: "~310", why: "Fixing palette and spacing to tokens removes an entire category of per-element decisions.", prompt: "Create and install a skill named `ui-tokens` (Tokens + Tailwind). It instructs the agent as follows: Style with Tailwind utilities for layout and spacing, on top of three color tokens (--ink, --paper, --accent) and a 4/8/16/32 scale. Keep preflight on as the consistent baseline — describe every margin, bullet, and underline explicitly, never rely on browser defaults. Two neutrals plus one accent, 1px borders, radii 6px/10px. Contrast >= 4.5:1 so the human eyeball verdict works. Color with meaning and measure: green confirms, red destroys or errors, blue informs — never subvert these. Hold roughly 60% neutral background, 30% structure and text, 10% high-contrast accent on interactive elements only. Layer tokens: raw option palettes stay private, decisions (accent, text) and component tokens are what code reads (Fowler, Material).  If the project already uses a different design system, do not create this skill at all — skip it.", checks: ["palette is 3 colors max", "no per-element color decisions", "contrast >= 4.5:1"] },
  { id: "ui-behavior", track: "ui", title: "Behavior contract", tokens: "~190", why: "Explicit text states make every outcome checkable by agents and humans alike, with no interpretation needed.", prompt: "Create and install a skill named `ui-behavior` (Behavior contract). It instructs the agent as follows: Every mutation needs an explicit state: idle → working → done|error. Show text status, never color alone. Respect prefers-reduced-motion. Confirm destructive actions inline. Humans verify by looking; log the state string for agents. For standard widgets (dialog, menu, combo, toggle, disclosure) follow the ARIA Authoring Practices pattern, keyboard behavior included — never invent interactions the platform already defined.", checks: ["each action exposes a text status", "reduced-motion honored", "destructive action confirms"] },
  { id: "code-shape", track: "code", title: "Machine-shaped modules", tokens: "~190", why: "Small typed modules fit in a single read, so the agent holds the whole unit in context at once.", prompt: "Create and install a skill named `code-shape` (Machine-shaped modules). It instructs the agent as follows: Write small flat Python modules: one file, one job, <150 lines. Typed inputs and outputs (Pydantic in, response_model out), no hidden globals, no clever abstractions. Flat over nested (depth <= 2, early returns). Raise HTTPException at boundaries; never leak tracebacks or raw errors. Name files by what they do: skills.py, validate.py, render.py.", checks: ["module <150 lines", "no global mutation", "tracebacks never reach clients"] },
  { id: "verify-tests", track: "verify", title: "Tests are the spec", tokens: "~160", why: "Tests are the only verdict both humans and agents can trust without reading the code.", prompt: "Create and install a skill named `verify-tests` (Tests are the spec). It instructs the agent as follows: Humans judge by tests, not by reading code. Ship one runnable check per behavior: one command (`./run.sh test`, `pytest`) must pass. Cover happy path + one edge (empty, oversized, unauthorized). Print PASS/FAIL lines an agent can parse.", checks: ["one command runs all checks", "edge case covered", "output is parseable"] },
  { id: "verify-visual", track: "verify", title: "Visual confirmation", tokens: "~220", why: "A screenshot settles in one glance what no code review can prove about a UI.", prompt: "Create and install a skill named `verify-visual` (Visual confirmation). It instructs the agent as follows: Humans judge UI by looking. Every screen needs a settled screenshot state with real data (no lorem, no empty list). List the 3 things to eyeball: layout, labels, error state. Save verification screenshots to the project's shots/ folder (gitignored), named for what they show — never /tmp. Never trust a headless screenshot alone: use it for a quick first look only, and treat a real browser or the user's own screenshot as proof; when they disagree, believe the user's screen. If it cannot be seen, it does not ship.", checks: ["seeded demo data present", "3 eyeball items listed", "error state visible"] },
  { id: "code-reuse", track: "code", title: "Reuse before you build", tokens: "~220", why: "Every line the agent doesn't write is tokens never spent and bugs never made.", prompt: "Create and install a skill named `code-reuse` (Reuse before you build). It instructs the agent as follows: Before writing anything new, look for a piece that already does the job: search the repo first, then the stack's own library — Flowbite components, Lucide icons, Lit or WebAwesome pieces, FastAPI and Pydantic helpers. Use the found piece as-is and adapt only what the task needs. When the same markup or logic appears twice, pull it into one shared helper or component where the next agent will find it — never paste a third copy. Hand-write only what no existing piece covers.", checks: ["no hand-built copy of a stocked piece", "repeated markup lives in one helper", "new pieces placed where agents will find them"] },
  { id: "code-group", track: "code", title: "Group by feature, drop the layers", tokens: "~220", why: "One folder holds the whole component, so the agent reads once instead of hunting across layers.", prompt: "Create and install a skill named `code-group` (Group by feature, drop the layers). It instructs the agent as follows: Organize new code by feature, not by layer: a component's files sit together — checkout_routes.py, checkout_models.py, checkout_tests.py — named <feature>_<kind> so everything is found in one place. Keep model/view/controller separation inside the folder, not across the codebase. Put truly shared definitions (Pydantic contracts) in one shared module every feature imports. If the codebase already uses a pattern like MVC, follow that pattern instead: restructuring working code costs tokens and every move risks new errors.", checks: ["feature files sit together", "shared facts live in one module", "house pattern followed over rewrites"] },
  { id: "ui-framework", track: "ui", title: "Islands first, house wins", tokens: "~260", why: "Standard web components with no build step; every new interactive region starts as one.", prompt: "Create and install a skill named `ui-framework` (Islands first, house wins). It instructs the agent as follows: Default to Lit islands for interactive regions, loaded from the pinned Lit CDN module — no build step, no framework lock-in. Lit ships no ready-made pieces, so keep Flowbite for those (menu, dialog, dropdown) and never rebuild one just to own it; if an island needs pieces, use WebAwesome over CDN; never React or Angular. Render into the light DOM (never shadow) so utilities and icons keep working; HTMX never targets an island or anything inside one. If the codebase already uses another framework, do not create this skill at all — skip it. If the project already uses a different stack, overwrite this skill with that stack's equivalent and follow it instead.", checks: ["no build step for components", "hx-target never targets an island", "light DOM so utilities keep working"] },
  { id: "ui-nav", track: "ui", title: "Responsive headers", tokens: "~210", why: "Navigation is the first thing a visitor meets; if it overflows on a phone the whole site looks broken.", prompt: "Create and install a skill named `ui-nav` (Responsive headers). It instructs the agent as follows: Show inline links on wide screens; below about 640px collapse them behind a hamburger button that opens a Flowbite dropdown (data-dropdown-toggle) — the library positions it as an overlay, so the open menu never pushes content down. Use a real nav landmark and a real button with an aria-label; Flowbite flips aria-expanded itself. Put the brand on its own centered row; stack the opened links vertically. No hand-written menu code, keyboard reachable.", checks: ["links fit without wrapping at 360px", "button flips aria-expanded", "keyboard can open and walk the menu"] },
  { id: "code-cache", track: "code", title: "Cache in layers, swap the store", tokens: "~200", why: "A cache hit skips work entirely — the cheapest token is the one never spent.", prompt: "Create and install a skill named `code-cache` (Cache in layers, swap the store). It instructs the agent as follows: Cache in layers, nearest first: HTTP (ETag plus 304, Cache-Control per content type), in-process memo for hot reads, CDN edge in front. Hide every layer behind one tiny interface — get, set, invalidate — so the store swaps without touching callers: memory today, Redis or Memcached tomorrow. Cache computed answers, never user-specific secrets. Invalidate on write (data changed), not on a timer alone.", checks: ["ETag and 304 on repeat reads", "one interface, swappable store", "invalidation tied to writes"] },
  { id: "code-track", track: "code", title: "Emit events, plug the sink later", tokens: "~210", why: "You can't improve what you never counted — and you can't un-leak what you logged.", prompt: "Create and install a skill named `code-track` (Emit events, plug the sink later). It instructs the agent as follows: Code emits events; sinks decide where they land. Call one tiny emit helper at the interesting moments — used, copied, failed, slow. The helper writes somewhere boring today (a local JSONL file) and a real sink tomorrow (ClickHouse, analytics) without callers changing. Count actions, never identities: no names, emails, or keys in events. Roll noisy events into buckets and surface them slowly, so displays stay readable and cheap.", checks: ["one emit helper everywhere", "no identities in events", "sink swaps without touching callers"] },
  { id: "ui-seo", track: "ui", title: "Be findable", tokens: "~250", why: "The best page is the one people actually find — humans through search, agents through the map.", prompt: "Create and install a skill named `ui-seo` (Be findable). It instructs the agent as follows: Every public page earns its visitors: one H1, a plain-words title under 60 characters, a meta description under 160 characters, semantic landmarks (header, main, footer), and real links — never JavaScript-only navigation. Ship a sitemap.xml listing every public page and name it in robots.txt; keep llms.txt current so agents find the machine doors too. Keep money behind the wall: premium content, checkout, billing, and account pages carry noindex and stay out of the sitemap — crawlers earn the free pages, never the paid ones. Keep pages light so they load fast on phones. Before adding a page or skill, check Google Trends for what people actually search — build where demand already exists, not where you guess it.", checks: ["one H1 plus meta title and description per page", "sitemap lists public pages only, paid pages noindexed", "Trends checked before new pages"] },
  { id: "code-perf", track: "code", title: "Fast by budget", tokens: "~210", why: "Users feel milliseconds and megabytes; everything else is invisible.", prompt: "Create and install a skill named `code-perf` (Fast by budget). It instructs the agent as follows: Set a budget first: page weight, endpoint milliseconds, query count — then measure before changing anything. Cache first (see code-cache): repeated work should never recompute. Shrink the payload: paginate lists, select only needed columns, compress images, ship less JavaScript. Push heavy work out of the request into background jobs (see code-async for the handoff), and turn N+1 reads into single joined or batched reads on indexed columns. Re-measure after every change; speed you can't see is a guess.", checks: ["budgets set before optimizing", "repeat work cached, not recomputed", "N+1 reads batched or joined"] },
  { id: "code-fallback", track: "code", title: "Shed load, keep serving", tokens: "~240", why: "Systems die when everything is equally critical; rank first, shed in order.", prompt: "Create and install a skill named `code-fallback` (Shed load, keep serving). It instructs the agent as follows: Rank every feature by criticality before trouble arrives: core serves, nice-to-haves shed first. Put each sheddable feature behind a flag so it turns off without a deploy. Under stress, serve stale cache, pause polling and beacons, and answer 429 with Retry-After on what's left — never crash the core to save the extras. Prove it with a stress test at multiples of peak load; an untested fallback is a wish. Group code by feature (see code-group) so a shed feature — or a future service split — follows existing seams instead of new surgery.", checks: ["features ranked by criticality", "shedding is flag-gated, not a deploy", "stress test proves the degraded mode"] },
  { id: "ui-forms", track: "ui", title: "Pick the right input", tokens: "~260", why: "Every extra click and scroll loses users; the right control asks nothing extra.", prompt: "Create and install a skill named `ui-forms` (Pick the right input). It instructs the agent as follows: For 2 to 4 options use radio buttons or segmented controls — everything visible, one click to answer. Use dropdowns only for 5 to 10 familiar options where space matters. Past 15 items use a combo box: a text input with live filtering so typing 2 or 3 characters isolates the target. For familiar data like birth years use plain numeric inputs, never long dropdown lists. Desktop hover menus wait 300 to 500 milliseconds before opening so passing cursors don't flicker them; prefer click-to-open menus. When one option suits most users, show it as the combo box default instead of giving all options equal weight (Microsoft).", checks: ["short lists use radio, not dropdowns", "15+ items get combo or text input", "hover menus carry 300-500ms delay"] },
  { id: "ui-index", track: "ui", title: "Interface work: pick interface skills", tokens: "~230", why: "One small map per area beats one giant map for everything.", prompt: "Create and install a skill named `ui-index` (Interface work: pick interface skills). It instructs the agent as follows: Your interface skills each do one job — never read them all. New screen or page → ui-shell, ui-tokens, ui-seo. New interactive piece (typing, dragging, live numbers) → ui-framework as well. Charts and graphs → ui-charts. Known widget (table, wizard, combo, calendar, modal, feed, kanban, editor, player, accordion) → ui-widgets, plus ui-platform-picks for library names and setup gates. Mobile app build → ui-mobile. Form inputs, dropdowns, menus → ui-forms. Page behavior and states → ui-behavior. Headers and navigation → ui-nav. Skip everything else. New codebase only: the house stack wins (see the bank map).", checks: ["only matched skills are read", "whole area never copied at once"] },
  { id: "ui-widgets", track: "ui", title: "Common widgets: library first, pinned shape", tokens: "~380", why: "Ten widgets cover most interface work in any framework — each pins the shape agents get wrong.", prompt: "Create and install a skill named `ui-widgets` (Common widgets: library first, pinned shape). It instructs the agent as follows: Never hand-build these ten — pick your ecosystem's stocked library (names per framework live in ui-platform-picks), build the pinned shape, and read only the named leaves. Data table → code-perf, code-reuse: page on the server where one exists, otherwise paginate client-side; render only the visible window. Multi-step wizard → ui-forms, ui-behavior: one state object at the wizard root, validate each step on exit. Combo and autocomplete → ui-forms, ui-behavior: debounce typing, abort the stale fetch. Calendar and date picker → ui-behavior, code-reuse: derive highlights from two boundary dates, never per-cell state. Modal, dialog, drawer → ui-behavior, code-reuse: trap focus inside, return it on close, unmount when shut. Chat and feed → code-perf, code-reuse: append-only updates, pin scroll to the newest message, unsubscribe on unmount. Kanban drag-drop → code-reuse, ui-behavior: columns hold card-id arrays, reorder by index splice, never mutate in place. Rich text editor → code-reuse: leave the editor uncontrolled, sync content on change only, never mirror keystrokes in component state. Media player → ui-behavior, code-reuse: drive sliders through a direct element handle, never rerender per frame. Accordion and tree sidebar → ui-behavior, ui-nav: one expanded id in state, never a boolean per item. Humans get the library's accessible piece with real labels and visible states; agents keep small typed pieces, colocated state, and stable keys around it.", checks: ["library picked before hand-building", "widget built in the pinned shape", "only named leaves read per widget", "controls labeled with visible states"] },
  { id: "ui-platform-picks", track: "ui", title: "Framework library names and setup gates", tokens: "~300", why: "The right library name per framework stops hand-building; the gate stops server patterns in client-only apps.", prompt: "Create and install a skill named `ui-platform-picks` (Framework library names and setup gates). It instructs the agent as follows: Read this only to resolve a library name or a setup gate, then go back to the task skill. Stocked picks per widget — table, kanban, editor, combo, calendar, dialog, accordion, wizard forms: React → TanStack Table, dnd-kit, TipTap, cmdk, react-day-picker, Radix, Radix, React Hook Form; Vue → TanStack Vue, Vue Draggable, TipTap, Headless UI Combobox, VueDatePicker, Reka, Reka, FormKit; Angular → Material table, CDK drag-drop, TipTap, Material autocomplete, Material datepicker, Material dialog, Material tree, Reactive Forms. Feeds and players need no library: subscribe and unsubscribe cleanly, drive the native media API. Setup gates — React: Next.js App Router allows server components behind a use-client boundary; standalone Vite or CRA is client-only, skip every server clause. Vue: Nuxt fetches on the server with useAsyncData and server/api routes; standalone Vite is client-only, skip every Nuxt clause. Angular: standalone components with signals, defer heavy regions, SSR only where the setup allows. New codebase with no framework yet: the house default wins (see ui-framework).", checks: ["names resolved here, nowhere else", "standalone setups skip server clauses", "new codebases defer to the house default"] },
  { id: "code-plan", track: "code", title: "Plan once, fetch once, run wide", tokens: "~320", why: "One batched fetch plus parallel independents beats sequential steps that each re-read.", prompt: "Create and install a skill named `code-plan` (Plan once, fetch once, run wide). It instructs the agent as follows: Count the task-matched skills — the always-on three and the maps don't count, they're fixed overhead. Crossing area maps is free — only matched leaves count. One or two — execute directly, no plan. Three or more — write the numbered plan before executing: inline if five steps or fewer in one live session, file if longer or interruptible. Each step names its skill and its exact done-state. Mark each step independent or blocked (naming the step it waits for); split mixed UI-plus-service jobs into per-track steps, each naming only its track's skills; execute all unblocked steps together, sequential only where one step's output feeds the next. Fetch every named skill once during planning, in one batched request — execution fetches nothing. If a step fails, fix the step — never rewrite the plan mid-flight without saying why. The last step is always cleanup: delete the plan file and every scratch file this task created — the tree holds only the deliverable plus its tests. Never delete anything you did not create; name anything uncertain in the final report instead of removing it.", checks: ["file only when long or interruptible", "independents run together, dependents wait", "all skills fetched once up front, none during execution", "tree holds only deliverable plus tests"] },
  { id: "app-index", track: "code", title: "Product features: pick product skills", tokens: "~280", why: "Billing, roles, and invites repeat in every system — map first, build the rest from shape.", prompt: "Create and install a skill named `app-index` (Product features: pick product skills). It instructs the agent as follows: Your product skills each do one job — never read them all. Billing and plans → code-billing. Team roles, admin console, impersonation → code-rbac. Invites and membership → code-invites. Notifications → code-notify. Search → code-search. Uploads → code-uploads. Audit trail → code-auditlog. Outgoing webhooks → code-webhooks. Customer API keys → code-apikeys. Flags and entitlements → code-flags. Bulk moves → code-impexp. Login and sessions → code-auth. Skip everything else.", checks: ["only matched product skills are read", "auth always via code-auth", "new product work metered with code-track"] },
  { id: "code-billing", track: "code", title: "Bill from plans, never hardcode", tokens: "~210", why: "Billing bugs refund money or lock out paying users — both fail loudly and publicly.", prompt: "Create and install a skill named `code-billing` (Bill from plans, never hardcode). It instructs the agent as follows: Bill from plan versions, never hardcoded amounts: every charge resolves price from the plan in effect when the metered event landed. Checkout sessions are idempotent — one customer plus plan plus idempotency key maps to one subscription. Fulfill and entitle only on signed provider webhooks, verified before trusting, with retry-safe handlers that converge on replay. Failed payments enter dunning (remind, retry, grace) before any cancel. Metered usage flows from code-track events, not from scattered counters. Prorate upgrades and downgrades at the switch, never at month end.", checks: ["no hardcoded prices", "entitlement only on verified webhooks", "dunning before cancel"] },
  { id: "code-rbac", track: "code", title: "Tenants, roles, safe impersonation", tokens: "~200", why: "One missing tenant check leaks a whole customer's data to another.", prompt: "Create and install a skill named `code-rbac` (Tenants, roles, safe impersonation). It instructs the agent as follows: Scope every row by tenant: a workspace id on every table, enforced server-side on every read and write — never by UI hiding alone (authentication lives in code-auth). Roles are least-privilege by default; check the permission at the action, not the role at login. Support tooling lives in a separate admin surface; impersonation requires a consent record plus an audit trail. Membership and invites live in code-invites.", checks: ["tenant id enforced server-side", "impersonation gated on consent plus audit", "membership changes via code-invites"] },
  { id: "data-index", track: "code", title: "Data work: pick data skills", tokens: "~300", why: "Pipelines fail in the same three places — landing, ordering, replay — map first.", prompt: "Create and install a skill named `data-index` (Data work: pick data skills). It instructs the agent as follows: Your data skills each do one job — never read them all. Collection strategy → data-collect. Landing events exactly once → data-ingest. Ordering tasks with retries and stall alerts → data-orchestrate. Batch transforms → data-etl. Schemas and evolution → data-contracts. Data representation → data-model. Backfill and replay → data-backfill. CDC → data-cdc. Quality gates → data-quality. Partitioning → data-partition. Retention → data-retain. Streams → data-streams. Lineage → data-lineage. Upserts → data-upserts. Concurrent writers → data-concurrency. Skip everything else.", checks: ["only matched data skills are read", "repeat patterns banked, not pasted"] },
  { id: "data-ingest", track: "code", title: "Land every event exactly once", tokens: "~200", why: "Without dedup keys every retry double-counts — revenue, usage, and analytics all inflate.", prompt: "Create and install a skill named `data-ingest` (Land every event exactly once). It instructs the agent as follows: Land every event exactly once: producers attach an idempotency key and retry freely; consumers dedup on that key before writing, so replays converge instead of double-counting. Validate against the schema first — reject unknown fields loudly, never silently drop. Poison events go to a dead-letter queue after N tries and page nobody; the stream never blocks on one bad record. Keep the dedup store bounded with a TTL past the retry window.", checks: ["retries converge, never double-count", "poison in DLQ, stream never blocks", "dedup store TTL-bounded"] },
  { id: "data-orchestrate", track: "code", title: "Pipelines as DAGs with stall SLAs", tokens: "~180", why: "Chained cron fails silently at 3am — explicit deps with stall alerts fail loudly instead.", prompt: "Create and install a skill named `data-orchestrate` (Pipelines as DAGs with stall SLAs). It instructs the agent as follows: Model every pipeline as a DAG with explicit dependencies — never chained cron that fails silently. Each task retries with backoff and declares its own stall SLA; breach pages, success stays quiet. Tasks must be idempotent so reruns converge. The scheduler owns ordering, retries, and alerts; the task owns one transform.", checks: ["deps explicit, no chained cron", "stall SLAs page, success quiet", "tasks idempotent"] },
  { id: "ops-index", track: "code", title: "Ops work: pick ops skills", tokens: "~300", why: "Deploys and pages follow the same gates everywhere — map first, improvise never.", prompt: "Create and install a skill named `ops-index` (Ops work: pick ops skills). It instructs the agent as follows: Your ops skills each do one job — never read them all. Build-test-deploy gates → ops-pipeline. Logs, metrics, traces, paging → ops-observe. Preview envs → ops-preview. Migrations → ops-migrate. Rollouts → ops-rollout. Secrets at runtime → ops-secrets. Backups and restore drills → ops-backup. Infra as code → ops-iac. Autoscaling → ops-scale. Health probes → ops-probes. Rotations and postmortems → ops-oncall. Two or more agents on one deploy or codebase → ops-coordinate. Humans verify the rollout dashboard and the drill record — never the procedure text; agents read the plan ledger and the deploy receipt instead. Skip everything else.", checks: ["only matched ops skills are read", "unproven ops work never ships"] },
  { id: "ops-pipeline", track: "code", title: "One template, gated deploys, one-button rollback", tokens: "~200", why: "Hand-rolled pipelines drift until the deploy that matters most is the one least tested.", prompt: "Create and install a skill named `ops-pipeline` (One template, gated deploys, one-button rollback). It instructs the agent as follows: Deploy only from one shared templated pipeline — never hand-rolled per repo. Required gates in order: build, tests, security scan, approval for production. Every deploy links to its commit; every PR gets a preview environment (see ops-preview). Broadcast deploy start and finish as machine-readable trigger events (see ops-observe) so agents and rollouts react without polling. Rollback means redeploying the previous known-good artifact with one action — never a new build under fire. Block on critical scan findings; ticket the rest with SLAs.", checks: ["one shared template, no hand-rolled pipes", "preview envs auto-stop", "rollback is one action on an old artifact"] },
  { id: "ops-observe", track: "code", title: "One id, actionable pages only", tokens: "~250", why: "Unactionable pages train the team to ignore the pager — then the real outage pages nobody.", prompt: "Create and install a skill named `ops-observe` (One id, actionable pages only). It instructs the agent as follows: Unify logs, metrics, and traces behind one request id so any alert opens the full story. Alert only on user-facing symptoms with a runbook link — every page must be actionable, or it becomes noise the team ignores. Emit every alert also as a signed, schema-versioned trigger event carrying the runbook link, so agents can auto-acknowledge or roll back without parsing human text. Dashboards are for debugging, not for watching; nothing pages that a dashboard could have shown quietly. Expose health as JSON endpoints and deploy receipts the agent can fetch — queryable signals first, dashboards second; use a monitoring MCP server when one exists. Never let the system be the only witness to its own health: keep one independent check — an external probe or status page outside the deploy — plus drill results a human can audit without asking the agent. Name the rotation that owns each alert; unowned alerts rot.", checks: ["one id across logs, metrics, traces", "every page actionable with runbook", "every alert has an owner"] },
  { id: "sec-index", track: "code", title: "Security ops: pick sec skills", tokens: "~300", why: "Vulns without owners sit for months — map first, scan-and-sit never.", prompt: "Create and install a skill named `sec-index` (Security ops: pick sec skills). It instructs the agent as follows: Your security-ops skills each do one job — never read them all. Known vulnerabilities → sec-vuln. Enterprise login, MFA, break-glass → sec-sso. App login basics → code-auth. Image and dependency scans → sec-scan. Leaked secrets → sec-secretscan. Sessions and tokens → sec-session. SIEM → sec-siem. WAF → sec-waf. Anomaly detection → sec-anomaly. Breach runbooks → sec-runbooks. Patching → sec-patch. Compliance evidence → sec-compliance. Hardening the code itself (validation, crypto, auth, sessions) → the OWASP deep-dives from the bank map you started with. Humans verify finding counts and drill logs — never the runbook text. Skip everything else.", checks: ["only matched sec skills are read", "app basics stay in code-auth"] },
  { id: "sec-vuln", track: "code", title: "Every finding owned with a deadline", tokens: "~190", why: "Scan-and-sit is the failure mode — findings without owners and SLAs age into breaches.", prompt: "Create and install a skill named `sec-vuln` (Every finding owned with a deadline). It instructs the agent as follows: Scan continuously and rank by exploitability, not by count: every finding gets an owner and a deadline scaled to reachability. Block the build on critical findings in CI and fail closed when the scanner errors — fail-open ships the vuln. Rescan to close; a finding without a retest stays open. Track mean-time-to-remediate per severity; scan-and-sit is the failure mode.", checks: ["every finding owned with a deadline", "CI fails closed on scanner errors", "closure requires retest"] },
  { id: "sec-sso", track: "code", title: "One IdP, expiring exceptions", tokens: "~190", why: "Permanent break-glass exceptions and legacy logins are the doors attackers walk through.", prompt: "Create and install a skill named `sec-sso` (One IdP, expiring exceptions). It instructs the agent as follows: Route every login through one identity provider — workforce and enterprise customers alike (app basics live in code-auth). Require phishing-resistant MFA; expire legacy password-only logins and break-glass exceptions with a date, never permanently. Provision just-in-time on first login from verified domains; deprovision automatically on IdP removal. Every exception carries an owner, an expiry, and an audit trail.", checks: ["one IdP, no permanent exceptions", "JIT provision, auto deprovision", "exceptions owned, expiring, audited"] },
  { id: "code-notify", track: "code", title: "Queued templated sends, never blocking", tokens: "~200", why: "Blocking inline sends turn every retry into a double-notify and every surge into a timeout.", prompt: "Create and install a skill named `code-notify` (Queued templated sends, never blocking). It instructs the agent as follows: Send every notification through a queue with a template — never blocking inline sends. Each user holds channel preferences (in-app, email, SMS, push); respect quiet hours with digested batches. Dedupe on event keys so retries never double-notify. Every outbound message carries a working unsubscribe; marketing and transactional never share a path.", checks: ["queued templated sends only", "dedupe keys, no double-notify", "working unsubscribe"] },
  { id: "code-search", track: "code", title: "Tenant-scoped, ranked, typo-tolerant", tokens: "~200", why: "Unscoped search leaks across customers; LIKE queries are the prototype, not the ship.", prompt: "Create and install a skill named `code-search` (Tenant-scoped, ranked, typo-tolerant). It instructs the agent as follows: Scope every query by tenant first — unscoped search leaks across customers. Rank by relevance, not recency; maintain the index on writes, never with a nightly rebuild the product outgrows. Typo tolerance and filters are table stakes. Log dead searches — they are the roadmap.", checks: ["tenant scoped, never global", "ranked, typo-tolerant", "index maintained on writes"] },
  { id: "code-uploads", track: "code", title: "Direct-to-storage, private by default", tokens: "~190", why: "Files through the app server bottleneck it; filenames lie; public buckets leak.", prompt: "Create and install a skill named `code-uploads` (Direct-to-storage, private by default). It instructs the agent as follows: Upload straight to storage with signed URLs — files never transit the app server. Trust MIME by content sniffing, never the filename; cap sizes at the edge. Scan asynchronously and quarantine on hit; serve everything private by default through signed URLs, never public buckets.", checks: ["direct-to-storage signed URLs", "MIME sniffed, sizes capped", "private by default"] },
  { id: "code-auditlog", track: "code", title: "Immutable actor-action-target trail", tokens: "~210", why: "Debug logs are not audit logs — auditors ask who did what, and noise is not an answer.", prompt: "Create and install a skill named `code-auditlog` (Immutable actor-action-target trail). It instructs the agent as follows: Record actor, action, target, and timestamp as immutable events — debug logs are not audit logs (break-in detection lives in code-logging). Any app with more than one user role — or with money, permissions, or exports — needs this whether or not HIPAA applies; regulated data only makes mandatory what multi-user accountability already requires. Keep the trail append-only with a retention policy and export for auditors. Log permission changes, data exports, and impersonation sessions first; those are the rows auditors ask for.", checks: ["immutable actor-action-target events", "retention plus export", "permission and export actions covered"] },
  { id: "code-webhooks", track: "code", title: "Signed payloads with replay", tokens: "~200", why: "Unsigned fire-and-forget posts leave customers debugging your deliveries with no tools.", prompt: "Create and install a skill named `code-webhooks` (Signed payloads with replay). It instructs the agent as follows: Sign every outbound payload so receivers can verify it; version the event schema. Retry with backoff on failure and keep a delivery log per destination with replay — customers debug with replays, not with your logs. Receivers dedup on event ids, so sending twice is safe. Never fire-and-forget.", checks: ["signed versioned payloads", "retry plus replay per destination", "delivery logs customer-visible"] },
  { id: "code-apikeys", track: "code", title: "Hashed, scoped, revocable keys", tokens: "~190", why: "A leaked plaintext key database hands attackers access; god-mode scopes hand them everything.", prompt: "Create and install a skill named `code-apikeys` (Hashed, scoped, revocable keys). It instructs the agent as follows: Store only hashes of customer API keys — a leaked database must not leak access. Scope every key least-privilege with per-key rate limits, rotation, and instant revocation. Show the secret once at creation, never again. Attribute every call to its key for metering and abuse tracing.", checks: ["hashes stored, shown once", "scoped with per-key limits", "instant revocation"] },
  { id: "code-flags", track: "code", title: "Targeted flags with owners and kill switches", tokens: "~190", why: "Scattered booleans with no owner become permanent; permanent flags become landmines.", prompt: "Create and install a skill named `code-flags` (Targeted flags with owners and kill switches). It instructs the agent as follows: Target every flag by plan, tenant, or rollout percent — never bare booleans scattered in code. Each flag has an owner, an audit trail, and a kill switch; stale flags get a removal date at creation. Entitlements (plan-gated features) ride the same system as experiments. Delete the flag when the rollout ends.", checks: ["targeted, never bare booleans", "owner plus kill switch", "stale flags removed"] },
  { id: "code-impexp", track: "code", title: "Bulk moves as background jobs", tokens: "~190", why: "Synchronous bulk queries time out, and one bad row should not kill the file.", prompt: "Create and install a skill named `code-impexp` (Bulk moves as background jobs). It instructs the agent as follows: Run every bulk import and export as a background job with progress — never a synchronous request that times out. Validate encoding and schema row by row, quarantining bad rows instead of failing the file. Page reads in bounded batches; the export that loads the whole table is the outage. Notify on completion with the error report attached.", checks: ["background jobs with progress", "bad rows quarantined, not fatal", "bounded batches"] },
  { id: "data-etl", track: "code", title: "Tested transforms, idempotent reloads", tokens: "~190", why: "Untested SQL with no idempotent reload turns every rerun into new duplicates.", prompt: "Create and install a skill named `data-etl` (Tested transforms, idempotent reloads). It instructs the agent as follows: Keep every transform in tested code with idempotent reloads — rerunning a date range converges, never duplicates. Business logic lives in reviewed, tested functions, not in untested SQL strings. Partition the reload unit by date so backfills touch days, not tables.", checks: ["transforms tested", "reloads idempotent by partition", "no untested SQL logic"] },
  { id: "data-contracts", track: "code", title: "Versioned schemas, additive only", tokens: "~190", why: "A breaking rename with no contract silently breaks every downstream reader.", prompt: "Create and install a skill named `data-contracts` (Versioned schemas, additive only). It instructs the agent as follows: Version every event and table schema in one registry with compatibility checks on publish. Additive changes only — new optional fields, never renames or type changes without a new version. Consumers pin the version they read; producers support the last N versions through a dual-write window.", checks: ["schemas versioned in one registry", "additive-only evolution", "consumers pin versions"] },
  { id: "data-backfill", track: "code", title: "Bounded throttled replays", tokens: "~190", why: "Full-table reruns overload sources and double-write; unmarked ranges confuse readers.", prompt: "Create and install a skill named `data-backfill` (Bounded throttled replays). It instructs the agent as follows: Backfill bounded partitions, throttled — never full-table reruns that overload sources. Writers stay idempotent so a retried partition converges; mark overwritten ranges so readers never see half-old, half-new. Backfills run below production priority with their own quota.", checks: ["bounded throttled partitions", "idempotent writers with markers", "below-prod priority"] },
  { id: "data-cdc", track: "code", title: "Stream the log, never poll", tokens: "~180", why: "API polling misses deletes and hammers the source; the log has every change in order.", prompt: "Create and install a skill named `data-cdc` (Stream the log, never poll). It instructs the agent as follows: Stream row inserts, updates, and deletes from the database log — deletes must propagate, which API polling can never do. Treat the log as the source of truth with ordered offsets; consumers checkpoint so restarts resume, never restart from zero.", checks: ["deletes propagate", "ordered offsets with checkpoints", "no polling"] },
  { id: "data-quality", track: "code", title: "Gate promotion on signals, not row counts", tokens: "~190", why: "Row counts pass plausible-but-wrong data; the bad numbers ship to every dashboard.", prompt: "Create and install a skill named `data-quality` (Gate promotion on signals, not row counts). It instructs the agent as follows: Gate every promotion on freshness, nulls, volume, and distribution — row counts alone pass plausible-but-wrong data. Failing checks block the pipeline and page the dataset owner, with the offending sample attached. Track quality history per dataset; sudden shifts are the incident.", checks: ["multi-signal gates, not row counts", "failures block with samples", "quality history tracked"] },
  { id: "data-partition", track: "code", title: "Prunable keys, no tiny files", tokens: "~180", why: "High-cardinality partitions spawn thousands of tiny files that slow every reader.", prompt: "Create and install a skill named `data-partition` (Prunable keys, no tiny files). It instructs the agent as follows: Partition by low-cardinality date or key so queries prune whole ranges. Never high-cardinality IDs — they spawn thousands of tiny files that slow every reader. Target files sized for the reader (tens to hundreds of MB); compact the small ones on a schedule.", checks: ["prunable low-cardinality keys", "no tiny-file sprawl", "compaction scheduled"] },
  { id: "data-retain", track: "code", title: "Expire per policy, prove deletion", tokens: "~180", why: "Keep-forever drowns storage budgets and turns every breach into a GDPR incident.", prompt: "Create and install a skill named `data-retain` (Expire per policy, prove deletion). It instructs the agent as follows: Expire or cold-store every dataset per written policy — cost and GDPR exposure both grow with keep-forever. PII gets the shortest retention and deletion on request with proof. Archive in open formats so cold data stays readable without the original cluster.", checks: ["policy per dataset, enforced", "PII deletable with proof", "open-format archives"] },
  { id: "data-streams", track: "code", title: "Windows plus watermarks", tokens: "~190", why: "Batch logic on streams mishandles late events; a stalled watermark is a silent outage.", prompt: "Create and install a skill named `data-streams` (Windows plus watermarks). It instructs the agent as follows: Transform unbounded streams with windows plus watermarks so late and out-of-order events settle correctly. Never batch logic on a stream — every unbounded grouping needs a trigger for when it emits. Track watermark lag as the health metric; a stalled watermark is the outage.", checks: ["windows plus watermarks", "every grouping has an emit trigger", "watermark lag monitored"] },
  { id: "data-lineage", track: "code", title: "Trace any number to its origin", tokens: "~180", why: "Tribal knowledge rots; a bad number with no origin takes days to explain.", prompt: "Create and install a skill named `data-lineage` (Trace any number to its origin). It instructs the agent as follows: Record which sources and transforms produced every dataset, automatically at run time — tribal knowledge rots. Any bad number traces to its origin in one lookup. Lineage rides the orchestrator's run records, not a wiki anyone must update.", checks: ["run-time recorded, never wiki", "one-lookup origin tracing"] },
  { id: "data-upserts", track: "code", title: "Merge by keys, never full overwrite", tokens: "~180", why: "Full overwrites waste the cluster and lose concurrent writes; lost watermarks drift forever.", prompt: "Create and install a skill named `data-upserts` (Merge by keys, never full overwrite). It instructs the agent as follows: Merge only new or changed rows by keys or watermarks — naive full overwrites waste the cluster and lose concurrent writes. Watermarks advance only after the merge commits; a crashed load resumes from the last committed mark, never from zero.", checks: ["keyed merges, no full overwrites", "watermarks advance on commit"] },
  { id: "ops-preview", track: "code", title: "Prod mirror per PR, auto-stopped", tokens: "~180", why: "Idle preview envs burn budget; prod dumps in previews leak customer data.", prompt: "Create and install a skill named `ops-preview` (Prod mirror per PR, auto-stopped). It instructs the agent as follows: Spin a production-mirror preview per PR with seeded demo data; destroy it on merge plus an idle timeout that auto-stops stragglers. Previews get anonymized data, never production dumps. The preview URL posts back to the PR so review happens before merge, not after.", checks: ["per-PR prod mirror", "auto-stop on merge plus idle", "no prod data in previews"] },
  { id: "ops-migrate", track: "code", title: "Expand then contract, always reversible", tokens: "~190", why: "Untested migrations with no rollback turn deploys into outages with no way back.", prompt: "Create and install a skill named `ops-migrate` (Expand then contract, always reversible). It instructs the agent as follows: Version every schema change and run it automatically with the deploy. Expand then contract: add nullable, backfill, constrain, drop — readers never see a half-migrated schema. Every migration reverses or pairs with its undo; never edit an applied migration, only add the next one. Dry-run against prod-shaped data before touching prod.", checks: ["expand-contract, never half-schemas", "reversible or paired", "dry-run on prod-shaped data"] },
  { id: "ops-rollout", track: "code", title: "Progressive traffic, predefined rollback", tokens: "~190", why: "Shipping 100% at once with no rollback trigger turns every bad deploy into a full outage.", prompt: "Create and install a skill named `ops-rollout` (Progressive traffic, predefined rollback). It instructs the agent as follows: Shift traffic progressively — canary then staged percentages — with health gates promoting each step. Define the rollback trigger before starting; rollback is one action that restores the last good version in minutes. Never 100% at once outside an emergency, and emergencies get a postmortem.", checks: ["health-gated progressive steps", "rollback trigger predefined", "rollback in minutes"] },
  { id: "ops-backup", track: "code", title: "Drilled restores timed to RTO", tokens: "~180", why: "An untested backup is assumed broken — teams discover it during the real outage.", prompt: "Create and install a skill named `ops-backup` (Drilled restores timed to RTO). It instructs the agent as follows: Back up on a schedule matched to a written RPO — and drill the restore, because an untested backup is assumed broken. Restores get timed against the RTO with the result recorded; a missed RTO changes the backup strategy, not the apology. Test restores into an isolated environment, never over production.", checks: ["RPO-matched schedule", "drilled restores timed to RTO", "isolated restore tests"] },
  { id: "ops-iac", track: "code", title: "Reproducible from a clean account", tokens: "~180", why: "Console click-ops leaves infra living in one engineer's head — unreviewed and unrepeatable.", prompt: "Create and install a skill named `ops-iac` (Reproducible from a clean account). It instructs the agent as follows: Define every environment version-controlled and reproducible from a clean account — console click-ops is never the source of truth. Plan output reviews before applies on shared environments; drift detection runs on a schedule and pages when reality diverges. State files are locked and backed up like production data.", checks: ["reproducible from clean account", "drift detection scheduled", "state locked and backed up"] },
  { id: "ops-scale", track: "code", title: "Bounded scaling on real signals", tokens: "~180", why: "Fixed counts idle-waste or collapse; unbounded scaling turns a spike into a billing incident.", prompt: "Create and install a skill named `ops-scale` (Bounded scaling on real signals). It instructs the agent as follows: Scale replicas on CPU, request rate, or queue depth — with min/max bounds so a metric spike cannot scale the bill to the moon. Scale the bottleneck resource, not everything; stateless first, stateful by runbook. Load-test the autoscaled path before the traffic spike finds it.", checks: ["bounded scaling on real signals", "stateless first", "autoscale path load-tested"] },
  { id: "ops-probes", track: "code", title: "Liveness split from readiness", tokens: "~180", why: "Instant-healthy sends traffic to broken pods mid-deploy; conflated probes restart what should drain.", prompt: "Create and install a skill named `ops-probes` (Liveness split from readiness). It instructs the agent as follows: Separate liveness (restart me) from readiness (send me traffic): a pod that cannot serve stays alive but out of rotation. Probes check real dependencies with timeouts — instant-healthy sends traffic to broken pods mid-deploy. Failing readiness sheds load; failing liveness restarts. Never probe with the same handler that serves users.", checks: ["liveness split from readiness", "probes check real deps", "no user-handler probes"] },
  { id: "ops-oncall", track: "code", title: "Rotation, runbooks, tracked postmortems", tokens: "~190", why: "The single-hero pager with no notes guarantees the same incident repeats.", prompt: "Create and install a skill named `ops-oncall` (Rotation, runbooks, tracked postmortems). It instructs the agent as follows: Page a scheduled rotation with escalation paths and severity levels — never a single hero with no notes (page-worthy symptoms live in ops-observe). Every page links its runbook; pages without runbooks get written during the incident review. Blameless postmortems within days, action items tracked to done — the review nobody reads is the incident that repeats.", checks: ["scheduled rotation with escalation", "runbook per page", "postmortems tracked to done"] },
  { id: "ops-coordinate", track: "code", title: "Agents share one plan, own one area", tokens: "~210", why: "Two agents writing the same deploy step — or stomping each other's files — is the new merge conflict.", prompt: "Create and install a skill named `ops-coordinate` (Agents share one plan, own one area). It instructs the agent as follows: When two or more agents share one deploy or one codebase, coordinate through artifacts, not chat: one shared plan file is the ledger (see code-plan) — claim a task before starting it, check it off when done, never start an unclaimed task. Own one feature directory per agent so parallel edits never touch the same files; crossing into another agent's area needs a plan note first. Prefer idempotent operations so a retried or doubled step converges instead of corrupting. Report status as structured records (task, result, artifact link), never prose another agent must parse. Humans verify the plan ledger and the deploy receipt — never the chat log.", checks: ["one shared plan ledger, tasks claimed", "one feature dir per agent", "status as records, not prose"] },
  { id: "sec-scan", track: "code", title: "Block builds on vuln images and deps", tokens: "~190", why: "Fail-open scanners and floating tags silently keep the CVE in production.", prompt: "Create and install a skill named `sec-scan` (Block builds on vuln images and deps). It instructs the agent as follows: Block builds on vulnerable base images and packages in CI — and fail closed when the scanner errors, because fail-open ships the vuln (runtime CVE ownership lives in sec-vuln). Pin versions and rebuild images on a schedule so fixes actually land; floating tags silently keep the CVE. Track mean-time-to-remediate; the scanner nobody watches is decoration.", checks: ["CI blocks on critical", "fail closed on scanner errors", "images pinned and rebuilt"] },
  { id: "sec-secretscan", track: "code", title: "Revoke first, purge history, block at push", tokens: "~190", why: "Alerting while the secret stays active fails; copies in history and forks outlive the fix.", prompt: "Create and install a skill named `sec-secretscan` (Revoke first, purge history, block at push). It instructs the agent as follows: Revoke the secret on detection first, investigate second — alerting while it stays active fails. Purge copies from history and forks, then rotate everything the secret could reach. Block commits containing known secret shapes at push time; detection after merge is the backup, not the plan.", checks: ["revoke first, investigate second", "history and forks purged", "push-time blocking"] },
  { id: "sec-session", track: "code", title: "Short-lived revocable sessions", tokens: "~180", why: "Long-lived JWTs with no revocation path stay valid after theft — the classic breach extender.", prompt: "Create and install a skill named `sec-session` (Short-lived revocable sessions). It instructs the agent as follows: Issue short-lived tokens with rotation and binding; keep server-side revocation so stolen sessions die on demand. Absolute lifetimes cap every session no matter how active. App login mechanics live in code-auth; this skill governs lifetimes and kill paths.", checks: ["short-lived with rotation", "server-side revocation", "absolute lifetime caps"] },
  { id: "sec-siem", track: "code", title: "Tamper-evident logs analysts can trust", tokens: "~190", why: "Logs nobody verifies won't survive scrutiny; alert floods train analysts to ignore the one that matters.", prompt: "Create and install a skill named `sec-siem` (Tamper-evident logs analysts can trust). It instructs the agent as follows: Aggregate auth, admin, and data-access events into tamper-evident searchable storage — and test the integrity, because logs nobody verifies won't survive scrutiny (product audit trails live in code-auditlog). Tune alerts to analyst capacity; unactioned floods train everyone to ignore the one that matters.", checks: ["tamper-evident with tested integrity", "alerts tuned to capacity"] },
  { id: "sec-waf", track: "code", title: "Blocking rules tuned to real traffic", tokens: "~180", why: "Monitor-only is decoration; copied defaults break legit users until someone disables everything.", prompt: "Create and install a skill named `sec-waf` (Blocking rules tuned to real traffic). It instructs the agent as follows: Run WAF and input-filter rules in blocking mode tuned to legitimate traffic — monitor-only is decoration, and copied defaults break real users until someone disables the whole thing. Payload shapes live in code-injection; the WAF enforces what that skill defines. Exempt nothing sensitive from logging; tune on false positives weekly after launch.", checks: ["blocking mode, tuned", "no monitor-only", "false positives tuned"] },
  { id: "sec-anomaly", track: "code", title: "Baselines retuned, sharp signals page", tokens: "~180", why: "Set-once thresholds decay into false-positive floods that bury the real attack.", prompt: "Create and install a skill named `sec-anomaly` (Baselines retuned, sharp signals page). It instructs the agent as follows: Baseline user, endpoint, and network behavior, then continuously retune — thresholds set once decay into false-positive floods everyone ignores. Promote only impossible-travel and lateral-movement class signals to pages; the rest stays in analyst review queues.", checks: ["baselines with continuous retuning", "only sharp signals page"] },
  { id: "sec-runbooks", track: "code", title: "Containment playbooks that get drilled", tokens: "~190", why: "Undrilled runbooks mean improvisation during the breach that matters.", prompt: "Create and install a skill named `sec-runbooks` (Containment playbooks that get drilled). It instructs the agent as follows: Write containment playbooks per breach class — isolation, credential rotation, customer notice — and drill them (rotation process lives in ops-oncall). Severity levels and escalation paths are decided in advance, not mid-breach. Every drill updates the playbook or it rots.", checks: ["containment per breach class", "drilled, not shelved", "drills update the playbook"] },
  { id: "sec-patch", track: "code", title: "Fleet-wide patching, no exemptions", tokens: "~180", why: "Exempted exec and legacy machines become the persistent foothold.", prompt: "Create and install a skill named `sec-patch` (Fleet-wide patching, no exemptions). It instructs the agent as follows: Push OS, browser, and agent updates fleet-wide with CIS baselines — including exec and legacy machines, because exemptions become the persistent foothold. Patch windows are scheduled and measured; unpatched stragglers page their owners.", checks: ["fleet-wide including exemptions", "measured patch windows"] },
  { id: "sec-compliance", track: "code", title: "Continuous automated evidence", tokens: "~230", why: "Week-before screenshots rot immediately and convince no auditor.", prompt: "Create and install a skill named `sec-compliance` (Continuous automated evidence). It instructs the agent as follows: Collect access reviews, change tickets, and control attestations continuously and automatically — screenshots the week before the audit rot immediately and convince nobody. Regulated data decides the control set, so identify it first: health data (HIPAA/PHI) → code-auditlog on every access, encryption at rest (see code-crypto), code-rbac tenant isolation, data-retain deletion with proof; card data (PCI) → never store PAN, tokenize through the provider; personal data (GDPR) → data-retain retention plus deletion on request. Build the controls first — evidence collection only proves what already exists. Map every control to the system that proves it; an unmapped control is an audit finding waiting.", checks: ["continuous automated collection", "every control mapped to proof"] },
  { id: "ops-secrets", track: "code", title: "Vault-injected secrets, rotated automatically", tokens: "~200", why: "Committed secrets and manual rotation scatter copies that outlive every fix.", prompt: "Create and install a skill named `ops-secrets` (Vault-injected secrets, rotated automatically). It instructs the agent as follows: Inject vault-backed secrets at runtime with RBAC — never commit secrets to repos or share one static value across environments. Rotate automatically on a schedule — no manual tickets, no copies in chat or env files. Audit every read; alert on reads from unexpected places.", checks: ["runtime injection only, never committed", "rotation automatic, no manual tickets", "reads audited"] },
  { id: "code-invites", track: "code", title: "Single-use invites, never ownerless", tokens: "~180", why: "Reusable invite links become backdoors; orphaned workspaces become undeletable.", prompt: "Create and install a skill named `code-invites` (Single-use invites, never ownerless). It instructs the agent as follows: Issue single-use expiring invite tokens, resendable on request — never reusable links or permanent codes. Accepting an invite grants exactly the invited role in exactly the invited workspace; membership changes are explicit events, also logged (see code-auditlog). A workspace never drops to zero owners — block the removal that would orphan it.", checks: ["single-use expiring tokens", "explicit role-scoped acceptance", "no ownerless workspaces"] },
  { id: "code-polyglot", track: "code", title: "Own guest-language code safely", tokens: "~260", why: "Guest code fails at the seam and in language-specific traps the Python-trained agent walks into.", prompt: "Create and install a skill named `code-polyglot` (Own guest-language code safely). It instructs the agent as follows: Use this only for code the house language technically cannot carry — Python remains the default everywhere else. Define the seam first: the contract lives in one repo as protobuf or JSON schema, and both sides generate from it — never hand-write both ends. Test the seam with recorded fixtures in the caller's language; the guest service proves itself with its own native tests, run with its native command (go test, cargo test, mix test). Keep guest code small and boring — the hot path only, everything else stays in Python. Agent pitfalls per guest: Rust — restructure ownership instead of cloning to satisfy the borrow checker. Go — propagate context and wrap errors; never swallow err. Erlang and Elixir — supervision trees own restarts, so don't defensively trap what the supervisor replays; keep state in processes.", checks: ["seam defined as generated contract", "seam tests with recorded fixtures", "guest code minimal, hot path only"] },
  { id: "verify-layout", track: "verify", title: "Layout proof: WCAG Reflow plus measured alignment", tokens: "~280", why: "WCAG Reflow is the published rulebook for the chop-and-scroll half; alignment is measured polish on top.", prompt: "Create and install a skill named `verify-layout` (Layout proof: WCAG Reflow plus measured alignment). It instructs the agent as follows: Follow WCAG 2.1 Reflow (1.4.10) as the rulebook: content usable with no loss and no two-dimensional scrolling at 320 CSS px width — except parts that genuinely need two dimensions (data tables, maps, diagrams, video, games), which scroll only inside a stocked component. Prove it with measurements from a real browser run — never from markup reading. Use the shot flow in verify-visual, driving it with Playwright where the repo has it. No chopped elements: every interactive element's bounding box sits fully inside the viewport at 320 CSS px and desktop widths. Aligned rows and columns: same-row controls share baselines, same-column edges line up — eyeball the shot, then assert the boxes. Prefer vertical page scroll; reach for a stocked component before any custom scroll region. The user overrules the skill: a purposely dense, playful, or brutalist design that breaks these rules ships as specified — flag the break, then build it. Save the proof shots to shots/ like verify-visual.", checks: ["no loss or 2D scroll at 320px (WCAG 1.4.10)", "rows share baselines, columns share edges", "2D scroll only in stocked components for exempt content"] },
  { id: "data-collect", track: "code", title: "Pull what can't push, cursor everything", tokens: "~200", why: "Polling without cursors re-reads or skips; sources that can push should never be polled.", prompt: "Create and install a skill named `data-collect` (Pull what can't push, cursor everything). It instructs the agent as follows: Let sources push when they can — webhooks in, landed by data-ingest. Poll only sources that can't push, and always with an ordered cursor (updated_at plus id, never page numbers) so restarts resume instead of re-reading or skipping. Ship logs, don't fetch them: servers forward append-only logs to the collector. Treat every collection path as at-least-once and put dedup at the landing — the collector retries freely, data-ingest converges. Backfill through the same cursor path with bounded ranges, never a separate full dump.", checks: ["push where possible, cursors where polling", "log shipping over fetching", "at-least-once plus landing dedup"] },
  { id: "ui-charts", track: "ui", title: "Charts humans can read, data agents already parsed", tokens: "~300", why: "Agents read tables; humans judge shapes — charts are the human verdict layer, not the analysis.", prompt: "Create and install a skill named `ui-charts` (Charts humans can read, data agents already parsed). It instructs the agent as follows: Aggregate on the server and ship only chart-ready rollups — never raw rows for the browser to group. Pick the chart by the question: trend over time goes line, comparison across few categories goes bar, parts of a whole goes stacked bar and never pie past five slices, distribution goes histogram, two variables goes scatter, live numbers go big text plus sparkline. Encode by the Cleveland-McGill ranking: position on a common scale beats length beats angle beats area beats color — bars beat pies and flat beats 3D for a measured reason (Cleveland & McGill, JASA 1984). Every chart gets what color alone can't carry: direct labels, a data table alongside (the W3C's prescribed long description for charts) plus, when interactive, a declarative Vega-Lite-style JSON spec — the agent judges and regenerates from table and spec, never from pixels — and axes that start at zero for bars. Reach for a stocked chart library (Apache ECharts, Recharts) instead of hand-drawn SVG. Humans read the shape to judge; agents already read the table — the chart convinces, the numbers underneath prove.", checks: ["server-aggregated rollups only", "chart matches the question", "labels plus table, never color alone"] },
  { id: "data-model", track: "code", title: "Data shaped for agent readers", tokens: "~270", why: "Agents re-parse every structure on every read — nesting, abbreviations, and clever nulls tax all of them.", prompt: "Create and install a skill named `data-model` (Data shaped for agent readers). It instructs the agent as follows: One canonical shape per concept: a User looks the same in the database, the API, and events — generated from one schema, never hand-mirrored. Flat over nested: nest at most two deep; deeper trees cost every reader a traversal, so lists of ids plus lookup beat giant trees. Names carry meaning: full words, units in names (amount_cents, created_at_utc), no tribal abbreviations. Explicit over clever: string enums spelled out, unions with a literal kind field, never null-means-something — use an explicit status instead. Time is ISO-8601 UTC strings, never local plus offset guessing. Validate at every boundary with Pydantic or Zod models so malformed data fails at the door with a message, not deep in logic. Denormalize for readers: store what queries read and recompute on write; joins across five tables cost the agent a reconstruction on every read. Respect the system it lands in: denormalization taxes writes, so keep hot write paths normalized; index what you filter, knowing each index taxes every write; events carry the change plus the id within the transport's size cap, never the whole entity; page everything bounded on read and write.", checks: ["one canonical shape per concept", "nesting at most two deep", "no null-means-something, units in names", "denormalization pays its write cost"] },
  { id: "data-concurrency", track: "code", title: "Concurrent writers converge, never clobber", tokens: "~220", why: "Two writers plus no locking equals lost updates — the bug that only appears in production.", prompt: "Create and install a skill named `data-concurrency` (Concurrent writers converge, never clobber). It instructs the agent as follows: Wrap multi-record changes in one database transaction — partial writes are corruption, not an edge case. Prefer optimistic locking: a version column on contested rows, retry the whole transaction on version mismatch, never hold a pessimistic lock across network calls. Make every write idempotent (see data-ingest) so the retry is safe to run twice. Shard hot rows — a single counter row updated by thousands of writers serializes everything; aggregate shards or buffer increments instead. Accept the database as the adult in the room: uniqueness, foreign keys, and check constraints enforced by the store beat application-level checks that race. Know your isolation default and what it hides; escalate only the transaction that proved it needs more.", checks: ["multi-record changes in one transaction", "optimistic locking with retry, no held locks", "hot rows sharded, not hammered"] },
  { id: "code-async", track: "code", title: "Slow work leaves the request", tokens: "~220", why: "Blocking the request on slow work times out users and cascades; unbounded fan-out stampedes everything downstream.", prompt: "Create and install a skill named `code-async` (Slow work leaves the request). It instructs the agent as follows: Default to synchronous for reads the user waits on — async is for work that outlives attention, not a faster way to do the same call. Hand slow work to a queue with a worker (see ops-pipeline for the deploy side): return a job id immediately, notify on completion like code-notify does, never hold the request open. Fan out with bounded concurrency — a fixed worker pool or semaphore, never unbounded spawns that stampede the downstream; gather results, and decide upfront whether one failure fails the batch or ships partial. CPU-bound work goes to a process pool, IO-bound to async tasks. Every background job is retryable and idempotent (see data-ingest), with its own stall SLA (see data-orchestrate); a silent dead worker is the failure mode.", checks: ["slow work leaves the request with a job id", "fan-out bounded, failure policy declared", "background jobs retryable with stall SLAs"] }
];

const FIELDS = ["id", "track", "title", "tokens", "why", "prompt", "checks"];
const pick = (s, f) => {
  if (!f) return s;
  const w = f.split(",").map((x) => x.trim()).filter((x) => FIELDS.includes(x));
  if (!w.length) return s;
  if (!w.includes("id")) w.unshift("id");
  return Object.fromEntries(w.map((x) => [x, s[x]]));
};
const etagOf = (b) => { let h = 5381; for (let i = 0; i < b.length; i++) h = ((h << 5) + h + b.charCodeAt(i)) >>> 0; return '"' + h.toString(16) + '"'; };
const json = (o, s = 200, req) => {
  const body = JSON.stringify(o);
  const tag = etagOf(body);
  if (req?.headers.get("if-none-match") === tag) return new Response(null, { status: 304, headers: { etag: tag } });
  return new Response(body, { status: s, headers: { "content-type": "application/json", etag: tag, "cache-control": "public, max-age=60" } });
};
const html = (b, s = 200) => new Response(b, { status: s, headers: { "content-type": "text/html; charset=utf-8" } });

function shell(title, inner) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title} — ai (愛) means love</title><style>body{font:16px/1.55 -apple-system,"Segoe UI",Helvetica,Arial,sans-serif;color:#16130e;max-width:860px;margin:0 auto;padding:32px 24px}h1{font-family:Georgia,serif}a{color:#b3400f}code{background:#f3f0e9;padding:2px 6px;border-radius:4px}nav{display:flex;gap:16px;margin-bottom:10px;flex-wrap:wrap;font-size:19px;font-weight:bold}.floatpills{display:flex;align-items:center;max-width:860px;margin:0 auto;padding:12px 24px 0}.floatpills a:last-child{margin-left:auto}.pill{font:12px/1.5 -apple-system,"Segoe UI",Helvetica,Arial,sans-serif;border:1px solid #b3400f;border-radius:999px;padding:2px 10px;text-decoration:none}.pill.solid{background:#b3400f;color:#fff}pre{background:#16130e;color:#f2ede3;padding:14px;border-radius:8px;overflow:auto}</style></head><body><nav><a href="/">ai (愛) means love</a><a href="/code">code</a><a href="/ui">ui</a><a href="/skills">skills</a></nav><div class="floatpills"><a class="pill solid" href="/#agent">${uses()} <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 4v11m0 0l-4-4m4 4l4-4M5 20h14"/></svg></a><a class="pill" style="margin-left:8px" href="/#support">support us</a></div>${inner}</body></html>`;
}

const STATS = { started: new Date().toISOString(), requests: 0, routes: {}, skills: {} };
const hit = (p, skill) => {
  STATS.requests++;
  STATS.routes[p] = (STATS.routes[p] || 0) + 1;
  if (skill) STATS.skills[skill] = (STATS.skills[skill] || 0) + 1;
};
const uses = () => (STATS.routes["/board.json"] || 0) + (STATS.routes["/api/skills"] || 0) + (STATS.routes["/api/skill/:id"] || 0);

export default {
  async fetch(req) {
    const url = new URL(req.url);
    const p = url.pathname;
    if (p === "/robots.txt") {
      hit(p);
      return new Response("User-agent: *\nAllow: /\n", { headers: { "content-type": "text/plain" } });
    }
    if (p === "/llms.txt") {
      hit(p);
      return new Response(["# ai (愛) means love", "Manifesto: machine builds for machines; humans verify via tests + visual check.", "", "## Machine endpoints (open, no key — free forever)", "- GET /api/skills[?track=&fields=]", "- GET /api/skill/:id[?fields=] (ETag → 304)", "- GET /api/stats (usage counts)", "", ...SKILLS.map((s) => `- skill ${s.id} [${s.track}] ${s.tokens}: ${s.title}`)].join("\n"), { headers: { "content-type": "text/plain" } });
    }
    if (p === "/api/skills") {
      hit(p);
      const t = url.searchParams.get("track");
      const f = url.searchParams.get("fields");
      const list = (t ? SKILLS.filter((s) => s.track === t) : SKILLS).map((s) => pick(s, f));
      return json({ ok: true, count: list.length, skills: list }, 200, req);
    }
    if (p.startsWith("/api/skill/")) {
      const id = p.slice(11);
      hit("/api/skill/:id", id);
      const s = SKILLS.find((x) => x.id === id);
      return s ? json({ ok: true, skill: pick(s, url.searchParams.get("fields")) }, 200, req) : json({ ok: false, error: "unknown skill" }, 404, req);
    }
    if (p === "/api/fields") {
      hit(p);
      return json({ ok: true, fields: FIELDS }, 200, req);
    }
    if (p === "/api/stats") {
      hit(p);
      return json({ ok: true, note: "in-memory on this isolate; resets on restart", stats: STATS }, 200, req);
    }
    if (p === "/board.json") {
      hit(p);
      return json({ ok: true, count: SKILLS.length, skills: SKILLS }, 200, req);
    }
    if (p === "/api" || p === "/keys") return Response.redirect(new URL("/skills", url).toString(), 302);
    if (p === "/board") return Response.redirect(new URL("/skills", url).toString(), 302);
    if (p === "/" || p === "/ui" || p === "/code" || p === "/skills") {
      hit(p);
      return html(shell(p, `<h1>ai (愛) means love</h1><p>New here? <a href="/#manifesto">Read the manifesto</a> first — four short points that explain the whole idea.</p><p>Machine builds for machines. Humans verify: tests pass + UI looks right.</p><p>Full interactive site runs from this repo (<code>./run.sh dev</code>). Machine endpoints are open, no key:</p><pre>GET /api/skills?fields=id,prompt\nGET /api/skill/code-secure?fields=prompt,checks\nGET /api/stats\nGET /llms.txt</pre><h2 id="agent">Give this to your agent</h2><p>Paste into any agent session — no key, no signup:</p><pre>curl https://aimeanslove.fyi/board.json\ncurl "https://aimeanslove.fyi/api/skills?track=code&fields=id,prompt"</pre><p>Or say: "Go to https://aimeanslove.fyi/board.json, read every skill, and install each one so you can use them."</p>`));
    }
    hit("404");
    return html(shell("missing", `<h1>Nothing here.</h1><p><a href="/">Back</a></p>`), 404);
  },
};
